class Dataman{constructor(){this.gen={token:this.token},this.parse={json:this.parse_json}}parse_json(t){try{return JSON.parse(t)}catch(r){return t}}crc32(t){for(var r,e=[],n=0;n<256;n++){r=n;for(var a=0;a<8;a++)r=1&r?3988292384^r>>>1:r>>>1;e[n]=r}for(var o=-1,s=0;s<t.length;s++)o=o>>>8^e[255&(o^t.charCodeAt(s))];return((-1^o)>>>0).toString(16)}jsonify=t=>{const r={},e=(Array(),Array()),n=t.querySelectorAll("input, select, textarea");for(var a=0;a<n.length;++a){const t=n[a],o=t.name,s=t.value;""!==o&&("checkbox"==t.type?r[o]=t.checked:"radio"==t.type?t.checked&&(r[o]=t.value):"select-multiple"==t.type?r[o]=JSON.stringify(self.getSelectValues(t)):t.classList.contains("dynamic_add")?e.push(t.value):o&&""!=s&&(r[o]=s))}return r};sha256=async t=>{const r=(new TextEncoder).encode(t),e=await crypto.subtle.digest("SHA-256",r);return Array.from(new Uint8Array(e)).map((t=>t.toString(16).padStart(2,"0"))).join("")};token(){return Math.random().toString(36).substring(2,15)+Math.random().toString(36).substring(2,15)}obj_blob(t){const r=JSON.stringify(t);return new Blob([r],{type:"application/json"})}}export default Dataman;